{
  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, service_name, metric, count(*) n, avg(value) v FROM abnormal_metrics WHERE service_name='recommendation' AND metric='k8s.deployment.available' GROUP BY ALL UNION ALL SELECT 'norm', service_name, metric, count(*), avg(value) FROM normal_metrics WHERE service_name='recommendation' AND metric='k8s.deployment.available' GROUP BY ALL",
          "claim": "Recommendation deployment availability drops to 0 during the incident (normal average 1.0) and stays there."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='recommendation' OR span_name LIKE 'recommendation.Recommendation%' GROUP BY ALL",
          "claim": "Recommendation server spans are absent in the abnormal period, while 448 normal ones were seen."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /recommendations' GROUP BY ALL",
          "claim": "Frontend /recommendations returns HTTP 500 with Error status for 135 requests, about 0.08 ms p50."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level='ERROR' GROUP BY ALL",
          "claim": "Frontend logs 113 ERROR entries reading 'Recommendation service failed'."
        }
      ]
    },
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms FROM abnormal_traces WHERE (service_name='search' AND span_name='rate.Rate/GetRates') OR (service_name='rate' AND attr_span_kind='Server') GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), approx_quantile(duration,0.5)/1e6 FROM normal_traces WHERE (service_name='search' AND span_name='rate.Rate/GetRates') OR (service_name='rate' AND attr_span_kind='Server') GROUP BY ALL",
          "claim": "search's client span to rate.GetRates rises to about 1.9 s p50, while rate's server span stays near 0.1 ms."
        },
        {
          "kind": "trace",
          "sql": "WITH s AS (SELECT span_id, duration d FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client'), r AS (SELECT parent_span_id, duration d FROM abnormal_traces WHERE service_name='rate' AND attr_span_kind='Server') SELECT count(*) n, approx_quantile(s.d-r.d,0.5)/1e6 gap_p50_ms FROM s JOIN r ON r.parent_span_id=s.span_id",
          "claim": "Paired search-to-rate calls show about 2 s of unexplained time per call on the connection, with rate's own processing time flat."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' GROUP BY ALL",
          "claim": "search's calls to geo on a different connection stay at about 0.6 ms, so the slowdown is specific to the rate connection."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, count(*) n, min(value) mn, max(value) mx FROM abnormal_metrics_sum WHERE service_name IN ('rate','search') AND metric='k8s.pod.uptime' GROUP BY ALL",
          "claim": "Search and rate uptimes run continuously with no reset, so neither pod restarted during the incident."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_span_kind, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='recommendation.Recommendation/GetRecommendations' GROUP BY ALL",
          "claim": "Frontend's client calls to recommendation fail with Error status in about 0.01 ms, so the failure reaches the user-facing /recommendations endpoint."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY ALL",
          "claim": "Frontend /hotels p95 rises to about 2.7 s, matching frontend's search.Search/Nearby client span."
        }
      ]
    }
  ]
}
